def parse_field(field: str, max_val: int) -> set[int]:
    terms = field.split(",")
    if len(terms) == 0:
        raise ValueError("field must have at least one term")

    result = set()
    for term in terms:
        result |= parse_term(term, max_val)

    return result


def parse_term(term: str, max_val: int) -> set[int]:
    # Check if the term has a /
    if "/" in term:
        parts = term.split("/")
        if len(parts) != 2:
            raise ValueError("term must have exactly one /")

        base = parts[0]
        step = int(parts[1])
        if step <= 0:
            raise ValueError("step must be >= 1")

        # Parse the base
        if base == "*":
            # Wildcard with step
            return set(range(0, max_val + 1, step))
        elif "-" in base:
            # Range with step
            parts_base = base.split("-")
            if len(parts_base) != 2:
                raise ValueError("invalid range")
            n = int(parts_base[0])
            m = int(parts_base[1])
            if n > m:
                raise ValueError("N > M")
            if n < 0 or m > max_val:
                raise ValueError("value out of range")
            return set(range(n, m + 1, step))
        else:
            # Single value with step
            n = int(base)
            if n < 0 or n > max_val:
                raise ValueError("value out of range")
            return set(range(n, max_val + 1, step))
    else:
        # No /
        if term == "*":
            # Wildcard
            return set(range(0, max_val + 1))
        elif "-" in term:
            # Range
            parts_base = term.split("-")
            if len(parts_base) != 2:
                raise ValueError("invalid range")
            n = int(parts_base[0])
            m = int(parts_base[1])
            if n > m:
                raise ValueError("N > M")
            if n < 0 or m > max_val:
                raise ValueError("value out of range")
            return set(range(n, m + 1))
        else:
            # Single value
            n = int(term)
            if n < 0 or n > max_val:
                raise ValueError("value out of range")
            return {n}
