class FairQueue:
    WAITING = 0
    PAUSED = 1
    RUNNING = 2

    def __init__(self, aging: int, cap: int):
        self.aging = aging
        self.cap = cap
        self._jobs = {}  # name -> (state, base_priority, waited, enqueue_counter)
        self._enqueue_counter = 0

    def submit(self, job, priority, t):
        if job in self._jobs:
            raise ValueError
        self._jobs[job] = (WAITING, priority, 0, self._enqueue_counter)
        self._enqueue_counter += 1

    def start(self, t):
        waiting_jobs = [(name, info) for name, info in self._jobs.items()
                        if info[0] == WAITING]
        waiting_jobs.sort(key=lambda x: (
            -(x[1][1] + min(self.cap, x[1][2] // self.aging)),  # effective priority
            -x[1][2],  # waited
            x[1][3]  # enqueue counter
        ))
        if not waiting_jobs:
            return None
        name, info = waiting_jobs[0]
        self._jobs[name] = (RUNNING, info[1], info[2], info[3])
        return name

    def finish(self, job, t):
        if job not in self._jobs:
            raise KeyError
        if self._jobs[job][0] != RUNNING:
            raise KeyError
        del self._jobs[job]

    def requeue(self, job, t):
        if job not in self._jobs:
            raise KeyError
        if self._jobs[job][0] != RUNNING:
            raise KeyError
        self._jobs[job] = (WAITING, self._jobs[job][1] - 1,
                           self._jobs[job][2], self._enqueue_counter)
        self._enqueue_counter += 1

    def pause(self, job, t) -> bool:
        if job not in self._jobs:
            raise KeyError
        if self._jobs[job][0] == WAITING:
            self._jobs[job] = (PAUSED, self._jobs[job][1],
                               self._jobs[job][2], self._jobs[job][3])
            return True
        elif self._jobs[job][0] == PAUSED:
            return False
        else:
            raise KeyError

    def resume(self, job, t) -> bool:
        if job not in self._jobs:
            raise KeyError
        if self._jobs[job][0] == PAUSED:
            self._jobs[job] = (WAITING, self._jobs[job][1],
                               self._jobs[job][2], self._jobs[job][3])
            return True
        elif self._jobs[job][0] == WAITING:
            return False
        else:
            raise KeyError

    def cancel(self, job) -> bool:
        if job not in self._jobs:
            return False
        del self._jobs[job]
        return True

    def queue(self, t) -> list[tuple[str, int]]:
        waiting_jobs = [(name, info) for name, info in self._jobs.items()
                        if info[0] == WAITING]
        waiting_jobs.sort(key=lambda x: (
            -(x[1][1] + min(self.cap, x[1][2] // self.aging)),  # effective priority
            -x[1][2],  # waited
            x[1][3]  # enqueue counter
        ))
        return [(name, x[1][1] + min(self.cap, x[1][2] // self.aging))
                for name, x in waiting_jobs]
