        raise ValueError("Both pattern and path must start with '/'")

    pattern_segments = pattern[1:].split('/')
    path_segments = path[1:].split('/')

    parsed = []
    names = set()

    for seg in pattern_segments:
        if seg.startswith(':'):
            name = seg[1:]
            if not re.match(r'^[A-Za-z0-9_]+$', name):
                raise ValueError(f"Invalid name: {name}")
            if name in names:
                raise ValueError(f"Duplicate name: {name}")
            names.add(name)
            if name.endswith('?'):
                parsed.append(('optional', name))
            else:
                parsed.append(('required', name))
        elif seg.startswith('#'):
            name = seg[1:]
            if not re.match(r'^[A-Za-z0-9_]+$', name):
                raise ValueError(f"Invalid name: {name}")
            if name in names:
                raise ValueError(f"Duplicate name: {name}")
            names.add(name)
            parsed.append(('digit', name))
        elif seg.startswith('*'):
            name = seg[1:]
            if not re.match(r'^[A-Za-z0-9_]+$', name):
                raise ValueError(f"Invalid name: {name}")
            if name in names:
                raise ValueError(f"Duplicate name: {name}")
            names.add(name)
            parsed.append(('wildcard', name))
        else:
            parsed.append(('literal', seg))

    captured = {}

    def backtrack(pattern_idx, path_idx):
        if pattern_idx == len(parsed):
            return path_idx == len(path_segments)

        seg_type, seg_name = parsed[pattern_idx]

        if seg_type == 'literal':
            if path_idx >= len(path_segments):
                return False
            if path_segments[path_idx] != seg_name:
                return False
            return backtrack(pattern_idx + 1, path_idx + 1)

        elif seg_type == 'required':
            if path_idx >= len(path_segments):
                return False
            if path_segments[path_idx] == '':
                return False
            captured[seg_name] = path_segments[path_idx]
            return backtrack(pattern_idx + 1, path_idx + 1)

        elif seg_type == 'digit':
            if path_idx >= len(path_segments):
                return False
            if not path_segments[path_idx].isdigit():
                return False
            captured[seg_name] = int(path_segments[path_idx])
            return backtrack(pattern_idx + 1, path_idx + 1)

        elif seg_type == 'optional':
            # Try 0 segments first (greedy minimization)
            if backtrack(pattern_idx + 1, path_idx):
                captured[seg_name] = None
                return True
            # Try 1 segment
            if path_idx < len(path_segments) and path_segments[path_idx] != '':
                captured[seg_name] = path_segments[path_idx]
                return backtrack(pattern_idx + 1, path_idx + 1)
            return False

        elif seg_type == 'wildcard':
            # Try 0 segments first (greedy minimization)
            if backtrack(pattern_idx + 1, path_idx):
                captured[seg_name] = []
                return True
            # Try increasing numbers of segments
            for num_segments in range(1, len(path_segments) - path_idx + 1):
                if path_idx + num_segments <= len(path_segments):
                    captured[seg_name] = path_segments[path_idx:path_idx + num_segments]
                    if backtrack(pattern_idx + 1, path_idx + num_segments):
                        return True
            return False

    if backtrack(0, 0):
        return captured
    return None
