import re
import math

def run_script(source: str, max_steps: int) -> tuple[list[int], str]:
    """Interpret a tiny language called 'Ember' and return (emitted_values, status)."""

    # Parse source into lines and tokens
    lines = source.split("\n")
    tokens_per_line = []
    for line in lines:
        tokens = line.split()
        tokens_per_line.append(tokens)

    # Static checking
    variables = {}
    open_blocks = []  # stack of (type, has_else)
    inside_while = False

    # Check for errors before execution
    for line_idx, tokens in enumerate(tokens_per_line):
        if not tokens:
            continue
        if tokens[0].startswith("#"):
            continue

        first_token = tokens[0]

        # Unknown first token
        if first_token not in ("set", "emit", "if", "while", "break", "skip", "halt", "else", "end"):
            raise ValueError("unknown first token")

        # Check for extra tokens after control keywords
        if first_token in ("else", "end", "break", "skip", "halt"):
            if len(tokens) > 1:
                raise ValueError("extra tokens after " + first_token)

        # Check set statement
        if first_token == "set":
            if len(tokens) < 3:
                raise ValueError("malformed set")
            name = tokens[1]
            if not re.match(r"[a-z]+", name):
                raise ValueError("malformed set (bad name)")
            if tokens[2] != "=":
                raise ValueError("malformed set (third token must be =)")
            # Check expression
            expr_tokens = tokens[3:]
            if not validate_expr(expr_tokens):
                raise ValueError("malformed expression")

        # Check emit statement
        if first_token == "emit":
            if len(tokens) < 2:
                raise ValueError("malformed emit")
            expr_tokens = tokens[1:]
            if not validate_expr(expr_tokens):
                raise ValueError("malformed expression")

        # Check if statement
        if first_token == "if":
            if len(tokens) < 2:
                raise ValueError("malformed if")
            expr_tokens = tokens[1:]
            if not validate_expr(expr_tokens):
                raise ValueError("malformed expression")
            # Push open block
            open_blocks.append(("if", False))

        # Check while statement
        if first_token == "while":
            if len(tokens) < 2:
                raise ValueError("malformed while")
            expr_tokens = tokens[1:]
            if not validate_expr(expr_tokens):
                raise ValueError("malformed expression")
            # Push open block
            open_blocks.append(("while", False))
            inside_while = True

        # Check else
        if first_token == "else":
            if not open_blocks:
                raise ValueError("else without open if")
            if open_blocks[-1][0] != "if":
                raise ValueError("else does not belong to an open if")
            if open_blocks[-1][1]:
                raise ValueError("else belongs to an if that already has an else")
            open_blocks[-1][1] = True

        # Check end
        if first_token == "end":
            if not open_blocks:
                raise ValueError("end with no open block")
            open_blocks.pop()
            if open_blocks and open_blocks[-1][0] == "while":
                inside_while = False

        # Check break
        if first_token == "break":
            if not inside_while:
                raise ValueError("break not inside any while")

        # Check skip
        if first_token == "skip":
            if not inside_while:
