def eval_tally(src: str, env: dict) -> int:
    """Evaluate an expression of the Tally language."""
    tokens = _tokenize(src)
    parser = _Parser(tokens, env)
    return parser.parse_expr()


def _tokenize(src):
    """Tokenize the source string."""
    tokens = []
    i = 0
    while i < len(src):
        # Check for two-character operators first
        if i + 1 < len(src) and src[i:i+2] in ('<=', '>=', '==', '!='):
            tokens.append(('op', src[i:i+2], i))
            i += 2
        elif src[i] in ('+', '-', '*', '/', '%', '^', '(', ')', '<', '>', '!', '&', '|', '?', ':'):
            tokens.append(('op', src[i], i))
            i += 1
        elif src[i] in (' ', '\t', '\n', '\r'):
            i += 1
        elif src[i] == '_' or src[i].isalpha():
            # Name
            j = i
            while j < len(src) and (src[j].isalnum() or src[j] == '_'):
                j += 1
            tokens.append(('name', src[i:j], i))
            i = j
        elif src[i].isdigit():
            # Integer literal
            j = i
            while j < len(src) and src[j].isdigit():
                j += 1
            tokens.append(('int', src[i:j], i))
            i = j
        else:
            # Illegal token
            tokens.append(('illegal', src[i], i))
            i += 1
    return tokens


class _Parser:
    """Recursive descent parser for the Tally language."""

    def __init__(self, tokens, env):
        self.tokens = tokens
        self.env = env
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def advance(self):
        if self.pos < len(self.tokens):
            self.pos += 1

    def parse_expr(self):
        """Parse a full expression (level 1)."""
        return self.parse_cond_expr()

    def parse_cond_expr(self):
        """Parse conditional: c ? a : b."""
        left = self.parse_level2_expr()
        if self.peek() and self.peek()[0] == 'op' and self.peek()[1] == '?':
            self.advance()
            right = self.parse_level2_expr()
            if self.peek() and self.peek()[0] == 'op' and self.peek()[1] == ':':
                self.advance()
                right = self.parse_expr()
                return self.eval_cond(left, right, right)
            else:
                raise ValueError("syntax", self.pos)
        return left

    def parse_level2_expr(self):
        """Parse level 2: left-associative |."""
        left = self.parse_level3_expr()
        while self.peek() and self.peek()[0] == 'op' and self.peek()[1] == '|':
            self.advance()
            right = self.parse_level2_expr()
            left = self.eval_or(left, right)
        return left

    def parse_level3_expr(self):
        """Parse level 3: left-associative &."""
        left = self.parse_level4_expr()
        while self.peek() and self.peek()[0] == 'op' and self.peek()[1] == '&':
            self.advance()
            right = self.parse_level3_expr()
            left = self.eval_and(left, right)
        return left

    def parse_level4_expr(self):
        """Parse level 4: comparisons (not associative)."""
        left = self.parse_level5_expr()
        if self.peek() and self.peek()[0] == 'op' and self.peek()[1] in ('<', '<=', '>', '>=', '==', '!='):
            op = self.peek()[1]
            self.advance()
            right = self.parse_level5_expr()
            return self.eval_comp(op, left, right)
        return left

    def parse_level5_expr(self):
        """Parse level 5: left-associative + and -."""
        left = self.parse_level6_expr()
        while self.peek() and self.peek()[0] == 'op' and self.peek()[1] in ('+', '-'):
            op = self.peek()[1]
            self.advance()
            right = self.parse_level5_expr()
            left = self.eval_bin(op, left, right)
        return left

    def parse_level6_expr(self):
        """Parse level 6: left-associative *, /, %."""
        left = self.parse_level7_expr()
        while self.peek() and self.peek()[0] == 'op' and self.peek()[1] in ('*', '/', '%'):
            op = self.peek()[1]
            self.advance()
            right = self.parse_level6_expr()
            left = self.eval_bin(op, left, right)
        return left

    def parse_level7_expr(self):
        """Parse level 7: unary prefix - and ! (may be repeated)."""
        left = self.parse_level8_expr()
        while self.peek() and self.peek()[0] == 'op' and self.peek()[1] in ('-', '!'):
            op = self.peek()[1]
            self.advance()
            right = self.parse_level7_expr()
            left = self.eval_unary(op, left)
        return left

    def parse_level8_expr(self):
        """Parse level 8: power (right-associative)."""
        left = self.parse_atom()
        if self.peek() and self.peek()[0] == 'op' and self.peek()[1] == '^':
            self.advance()
            right = self.parse_level7_expr()
            return self.eval_pow(left, right)
        return left

    def parse_atom(self):
        """Parse an atom: literal, name, or (expression)."""
        token = self.peek()
        if token is None:
            raise ValueError("syntax", len(self.tokens))
        if token[0] == 'int':
            self.advance()
            return int(token[1])
        elif token[0] == 'name':
            self.advance()
            if token[1] not in self.env:
                raise ValueError("name", token[2])
            return self.env[token[1]]
        elif token[0] == 'op' and token[1] == '(':
            self.advance()
            result = self.parse_expr()
            if self.peek() and self.peek()[0] == 'op' and self.peek()[1] == ')':
                self.advance()
                return result
            else:
                raise ValueError("syntax", self.pos)
        else:
            raise ValueError("syntax", token[2])

    def eval_cond(self, c, a, b):
        """Evaluate conditional: c ? a : b."""
        c = self.parse_expr()
        if c != 0:
            return self.parse_expr(a)
        else:
            return self.parse_expr(b)

    def eval_or(self, a, b):
        """Evaluate a | b."""
        if a != 0:
            return 1
        else:
            return self.parse_expr(b)

    def eval_and(self, a, b):
        """Evaluate a & b."""
        if a == 0:
            return 0
        else:
            return 1 if b != 0 else 0

    def eval_comp(self, op, a, b):
        """Evaluate comparison."""
        if op == '<':
            return 1 if a < b else 0
        elif op == '<=':
            return 1 if a <= b else 0
        elif op == '>':
            return 1 if a > b else 0
        elif op == '>=':
            return 1 if a >= b else 0
        elif op == '==':
            return 1 if a == b else 0
        elif op == '!=':
            return 1 if a != b else 0
        else:
            raise ValueError("syntax", self.pos)

    def eval_bin(self, op, a, b):
        """Evaluate binary operator."""
        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '*':
            return a * b
        elif op == '/':
            if b == 0:
                raise ValueError("div", self.pos)
            # Truncate toward zero
            if a >= 0:
                return a // b
            else:
                return -(-a // b)
        elif op == '%':
            if b == 0:
                raise ValueError("div", self.pos)
            # a % b = a - b * (a / b) with truncation toward zero
            return a - b * (a // b if a >= 0 else -(-a // b))
        else:
            raise ValueError("syntax", self.pos)

    def eval_unary(self, op, a):
        """Evaluate unary operator."""
        if op == '-':
            return -a
        elif op == '!':
            return 1 if a == 0 else 0
        else:
            raise ValueError("syntax", self.pos)

    def eval_pow(self, a, b):
        """Evaluate power."""
        if b < 0:
            raise ValueError("exp", self.pos)
        if a == 0 and b == 0:
            return 1
        return a ** b
