import collections


class VaultKV:
    def __init__(self):
        self._data = {}
        self._locks = {}
        self._reverse = collections.defaultdict(set)
        self._transactions = []

    def put(self, key, value):
        if self._locked(key):
            raise PermissionError
        old_value = self._data.get(key)
        self._data[key] = value
        if old_value is not None:
            self._reverse[old_value].discard(key)
        self._reverse[value].add(key)

    def get(self, key, default=None):
        return self._data.get(key, default)

    def drop(self, key):
        if self._locked(key):
            raise PermissionError
        if key not in self._data:
            return False
        value = self._data[key]
        del self._data[key]
        self._reverse[value].discard(key)
        return True

    def incr(self, key, by=1):
        if self._locked(key):
            raise PermissionError
        if key not in self._data:
            self._data[key] = 0
        value = self._data[key]
        if not isinstance(value, int):
            raise TypeError
        self._data[key] = value + by
        old_value = value
        self._reverse[old_value].discard(key)
        self._reverse[self._data[key]].add(key)

    def holders(self, value):
        return sorted(self._reverse.get(value, set()))

    def size(self):
        return len(self._data)

    def lock(self, key):
        self._locks[key] = True

    def unlock(self, key):
        self._locks[key] = False

    def locked(self, key):
        return self._locks.get(key, False)

    def begin(self, name=None):
        self._transactions.append({
            'name': name,
            'data': [],
            'locks': [],
            'depth': len(self._transactions)
        })

    def commit(self):
        if not self._transactions:
            raise RuntimeError
        txn = self._transactions.pop()
        for key, value in txn['data']:
            self._data[key] = value
            self._reverse[value].add(key)
        for key, locked in txn['locks']:
            self._locks[key] = locked
        return len(self._transactions)

    def rollback(self, name=None):
        if not self._transactions:
            raise RuntimeError
        if name is None:
            txn = self._transactions.pop()
            for key, value in reversed(txn['data']):
                if value is None:
                    del self._data[key]
                    self._reverse.get(self._data.get(key, None), set()).add(key)
                else:
                    self._data[key] = value
                    self._reverse[value].add(key)
            for key, locked in reversed(txn['locks']):
                self._locks[key] = locked
            return len(self._transactions)
        else:
            for i, txn in enumerate(self._transactions):
                if txn['name'] == name:
                    break
            if i == len(self._transactions):
                raise KeyError
            for j in range(i, len(self._transactions)):
                self._transactions.pop()
            for key, value in reversed(self._transactions[-1]['data']):
                if value is None:
                    del self._data[key]
                    self._reverse.get(self._data.get(key, None), set()).add(key)
                else:
                    self._data[key] = value
                    self._reverse[value].add(key)
            for key, locked in reversed(self._transactions[-1]['locks']):
                self._locks[key] = locked
            return len(self._transactions)

    def depth(self):
        return len(self._transactions)
