def reflow(src: str, width: int) -> str:
    """Parse text in Lath notation and reflow it into a canonical layout."""
    items = parse(src)
    if not items:
        return ""
    result = []
    for item in items:
        result.append(reflow_item(item, 0, 0, width))
    return "\n".join(result)

def parse(src: str) -> list:
    """Parse Lath notation into a list of items."""
    items = []
    i = 0
    while i < len(src):
        # Skip whitespace
        while i < len(src) and src[i] in ' \t\n\r':
            i += 1
        if i >= len(src):
            break
        if src[i] == '"':
            # Parse string
            i += 1
            s = ''
            while i < len(src):
                if src[i] == '\\':
                    i += 1
                    if i < len(src):
                        s += src[i]
                    else:
                        s += '\\'
                elif src[i] == '"':
                    i += 1
                    break
                else:
                    s += src[i]
                i += 1
            items.append(('string', s))
        elif src[i] == ';':
            # Skip comment
            while i < len(src) and src[i] != '\n':
                i += 1
            if i < len(src):
                i += 1  # skip newline
        elif src[i] == '(' or src[i] == '[':
            # Parse list
            bracket = src[i]
            i += 1
            inner = parse_list(src, i)
            # Find matching closing bracket
            depth = 1
            while i < len(src):
                if src[i] == bracket:
                    depth -= 1
                    if depth == 0:
                        i += 1
                        break
                elif src[i] == bracket:
                    depth += 1
                i += 1
            items.append(('list', bracket, inner))
        else:
            # Parse atom
            j = i
            while j < len(src) and src[j] not in ' \t\n\r( ) [ ] " ;':
                j += 1
            items.append(('atom', src[i:j]))
            i = j
    return items

def parse_list(src: str, start: int) -> list:
    """Parse a list starting at position start."""
    items = []
    i = start
    while i < len(src):
        # Skip whitespace
        while i < len(src) and src[i] in ' \t\n\r':
            i += 1
        if i >= len(src):
            break
        if src[i] == '"':
            i += 1
            s = ''
            while i < len(src):
                if src[i] == '\\':
                    i += 1
                    if i < len(src):
                        s += src[i]
                    else:
                        s += '\\'
                elif src[i] == '"':
                    i += 1
                    break
                else:
                    s += src[i]
                i += 1
            items.append(('string', s))
        elif src[i] == ';':
            while i < len(src) and src[i] != '\n':
                i += 1
            if i < len(src):
                i += 1
        elif src[i] == '(' or src[i] == '[':
            bracket = src[i]
            i += 1
            inner = parse_list(src, i)
            depth = 1
            while i < len(src):
                if src[i] == bracket:
                    depth -= 1
                    if depth == 0:
                        i += 1
                        break
                elif src[i] == bracket:
                    depth += 1
                i += 1
            items.append(('list', bracket, inner))
        else:
            j = i
            while j < len(src) and src[j] not in ' \t\n\r( ) [ ] " ;':
                j += 1
            items.append(('atom', src[i:j]))
            i = j
    return items

def flat(item: tuple) -> str:
    """Compute the FLAT form of an item."""
    if item[0] == 'atom':
        return item[1]
    elif item[0] == 'string':
        return item[1]
    elif item[0] == 'list':
        bracket = item[1]
        inner = item[2]
        if not inner:
            return bracket + bracket
        return bracket + ' '.join(flat(i) for i in inner) + bracket

def reflow_item(item: tuple, col: int, trail: int, width: int) -> str:
    """Render an item at column col with trail closing brackets."""
    if item[0] == 'atom' or item[0] == 'string':
        return item[1]
    elif item[0] == 'list':
        bracket = item[1]
        inner = item[2]
        flat_form = flat(item)
        if not inner or col + len(flat_form) + trail <= width:
            return flat_form
        # Break the list
        if bracket == '(' and inner[0][0] == 'atom' and len(inner) >= 2:
            # HEAD STYLE
            first = flat(inner[0])
            lines = [bracket + first]
            for i in range(1, len(inner)):
                lines.append(' ' * (col + 2) + flat(inner[i]))
            # Closing bracket on last line
            last_line = lines[-1]
            lines[-1] = last_line + bracket
            return '\n'.join(lines)
        else:
            # BLOCK STYLE
            first = flat(inner[0])
            lines = [bracket + first]
            for i in range(1, len(inner)):
                lines.append(' ' * (col + 1) + flat(inner[i]))
            # Closing bracket on last line
            last_line = lines[-1]
            lines[-1] = last_line + bracket
            return '\n'.join(lines)
